css:
:root{
 --brand:#61BBDC;--brand-soft:#8FD0E7;--brand-wash:#EAF5FA;--brand-tint:#D4EAF4;
 --sage:#BADBC3;--sage-soft:#D3E8DA;--sage-wash:#F0F7F2;--sage-tint:#DCEEE2;
 --ink:#0E3A4A;--ink-soft:#1C5064;--body:#44575E;--muted:#5B6E75;
 --paper:#fff;--cream:#F7FBFD;--sand:#EDF6FA;--line:#DCEAF0;--line-2:#C3DEEA;
 --r-sm:10px;--r:14px;--r-lg:22px;--r-xl:34px;--r-pill:999px;
 --ff-head:'Plus Jakarta Sans',system-ui,Arial,sans-serif;--ff-body:'Inter',system-ui,Arial,sans-serif;
 --gut:clamp(18px,4.2vw,56px);--band:clamp(58px,7vw,108px);--maxw:1280px;--t:.25s ease;
 --sh-1:0 2px 8px rgba(14,58,74,.05);--sh-2:0 18px 44px -26px rgba(14,58,74,.3);--sh-3:0 36px 80px -38px rgba(14,58,74,.4);
 --dots:radial-gradient(rgba(97,187,220,.45) 1.7px,transparent 1.7px);
 --dots-sage:radial-gradient(rgba(186,219,195,.85) 1.7px,transparent 1.7px);
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--body);font-family:var(--ff-body);font-size:17px;line-height:1.7;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--ff-head);color:var(--ink);margin:0 0 .5em;line-height:1.15;font-weight:800;letter-spacing:-.018em}
h1{font-size:clamp(2.15rem,4.5vw,3.6rem)}
h2{font-size:clamp(1.8rem,3.4vw,2.7rem)}
h3{font-size:1.2rem;font-weight:700}
p{margin:0 0 1.05em}
a{color:var(--ink)}
img{max-width:100%;height:auto;display:block}
ul{margin:0 0 1em;padding-left:1.1em}
strong{color:var(--ink)}
svg{width:18px;height:18px;flex-shrink:0;fill:currentColor}
.ico-l{fill:none;stroke:currentColor;stroke-width:2.1;stroke-linecap:round;stroke-linejoin:round}
.ico-l *{vector-effect:non-scaling-stroke}
:focus-visible{outline:3px solid var(--ink);outline-offset:3px;border-radius:6px}
.wrap{width:100%;max-width:var(--maxw);margin-inline:auto;padding-inline:var(--gut)}
.band{padding-top:var(--band);padding-bottom:var(--band);position:relative;overflow:hidden}
.band.ovis{overflow:visible;z-index:5}
.sr-only{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip{position:absolute;left:-9999px;top:0;background:var(--brand);color:var(--ink);padding:12px 20px;z-index:200;border-radius:0 0 8px 0;font-weight:700}
.skip:focus{left:0}
.b-cream{background:var(--cream)}
.b-sand{background:var(--sand)}
.b-sage{background:var(--sage-wash)}
.b-wash{background:var(--brand-wash)}
.b-dots{position:relative}
.b-dots::before{content:"";position:absolute;inset:0;background-image:var(--dots);background-size:19px 19px;opacity:.5;pointer-events:none}
.b-dots>.wrap{position:relative;z-index:1}
/* eyebrow */
.eyebrow{display:inline-flex;align-items:center;gap:.55em;font-family:var(--ff-head);font-weight:700;font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:var(--r-pill);padding:9px 18px 9px 13px;margin:0 0 1.05rem;box-shadow:var(--sh-1)}
.eyebrow svg{width:15px;height:15px;color:var(--brand)}
.lede{font-size:clamp(1.02rem,1.25vw,1.14rem);color:var(--body);max-width:62ch}
.sec-head{max-width:72ch;margin-bottom:clamp(30px,3.8vw,54px);position:relative;z-index:1}
.sec-head.center{margin-inline:auto;text-align:center}
.sec-head.center .lede{margin-inline:auto}
.mark{background:var(--brand);color:var(--ink);padding:.02em .3em;border-radius:8px;box-decoration-break:clone;-webkit-box-decoration-break:clone}
/* buttons + animation */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.6em;font-family:var(--ff-head);font-weight:700;font-size:1rem;line-height:1.1;padding:15px 26px;border-radius:var(--r-pill);border:1.5px solid transparent;cursor:pointer;text-decoration:none;min-height:56px;position:relative;overflow:hidden;isolation:isolate;white-space:nowrap;color:var(--ink);background:var(--brand);border-color:var(--brand);
 transition:transform .28s cubic-bezier(.34,1.3,.64,1),box-shadow .28s ease,background-color var(--t),border-color var(--t),color var(--t)}
.btn::after{content:"";position:absolute;top:0;left:-140%;width:55%;height:100%;z-index:-1;transform:skewX(-22deg);background:linear-gradient(90deg,transparent,rgba(255,255,255,.65),transparent);transition:left .6s ease}
.btn:hover::after{left:150%}
.btn:hover{transform:translateY(-3px);box-shadow:0 16px 30px -14px rgba(14,58,74,.4)}
.btn:active{transform:translateY(-1px)}
.btn svg{width:16px;height:16px}
.btn .ic{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.55);transition:transform .3s cubic-bezier(.34,1.3,.64,1),background-color var(--t)}
.btn:hover .ic{transform:translateX(4px) rotate(-8deg);background:#fff}
.btn-primary{background:var(--brand);border-color:var(--brand);color:var(--ink)}
.btn-primary:hover{background:var(--sage);border-color:var(--sage)}
.btn-action{background:var(--sage);border-color:var(--sage);color:var(--ink)}
.btn-action:hover{background:var(--brand);border-color:var(--brand)}
.btn-ghost{background:transparent;color:var(--ink);border-color:var(--line-2)}
.btn-ghost .ic{background:var(--brand-wash)}
.btn-ghost:hover{border-color:var(--brand);background:var(--brand-wash)}
.btn-white{background:#fff;color:var(--ink);border-color:#fff}
.btn-white .ic{background:var(--brand-wash)}
.btn-white:hover{background:var(--sage);border-color:var(--sage)}
.btn-sm{padding:11px 20px;font-size:.9rem;min-height:46px}
.btn-sm .ic{width:26px;height:26px}
/* flashy header CTA */
.btn-flash{background:linear-gradient(100deg,var(--brand) 0%,var(--sage) 50%,var(--brand) 100%);background-size:220% 100%;border-color:transparent;color:var(--ink);font-weight:800;letter-spacing:.01em;box-shadow:0 10px 24px -12px rgba(97,187,220,.95);animation:flashSheen 5s linear infinite,flashPulse 2.8s ease-in-out infinite}
.btn-flash:hover{animation-play-state:paused;transform:translateY(-3px) scale(1.035);box-shadow:0 18px 34px -12px rgba(97,187,220,1)}
.btn-flash .spark{width:17px;height:17px;color:var(--ink);animation:sparkle 2.4s ease-in-out infinite}
@keyframes flashSheen{0%{background-position:140% 0}100%{background-position:-60% 0}}
@keyframes flashPulse{0%,100%{box-shadow:0 10px 24px -12px rgba(97,187,220,.9)}50%{box-shadow:0 14px 34px -10px rgba(97,187,220,1)}}
@keyframes sparkle{0%,100%{transform:scale(1) rotate(0);opacity:.85}50%{transform:scale(1.22) rotate(14deg);opacity:1}}
.lnk{font-family:var(--ff-head);font-weight:700;font-size:.92rem;color:var(--ink);display:inline-flex;align-items:center;gap:.5em;text-decoration:none;padding-bottom:2px;background-image:linear-gradient(var(--brand),var(--brand));background-size:0 2px;background-repeat:no-repeat;background-position:0 100%;transition:background-size .3s ease}
.lnk:hover{background-size:100% 2px}
.lnk svg{width:14px;height:14px;color:var(--brand);transition:transform var(--t)}
.lnk:hover svg{transform:translateX(4px)}
/* diamond figure */
.dia{position:relative;width:min(100%,480px);margin-inline:auto;aspect-ratio:1/1}
.dia-in{position:absolute;inset:9%;transform:rotate(45deg);border-radius:30%;overflow:hidden;background:var(--brand-wash);box-shadow:var(--sh-3)}
.dia-in img{width:100%;height:100%;object-fit:cover;object-position:54% 50%;transform:rotate(-45deg) scale(1.44);transform-origin:center}
.dia-arc{position:absolute;inset:3%;transform:rotate(45deg);border-radius:32%;border:9px solid var(--brand);border-top-color:transparent;border-right-color:transparent;pointer-events:none}
.dia-dots{position:absolute;width:132px;height:112px;background-image:var(--dots);background-size:13px 13px;pointer-events:none}
/* the decorative patch would double up on sections that already carry the dot pattern */
.hero .dia-dots,.phero .dia-dots,.b-dots .dia-dots{display:none}
.dia-badge{position:absolute;z-index:3;left:-14px;bottom:30px;width:106px;height:106px;border-radius:24px;background:var(--brand);color:var(--ink);display:grid;place-content:center;text-align:center;box-shadow:var(--sh-2);border:5px solid #fff}
.dia-badge b{display:block;font-family:var(--ff-head);font-weight:800;font-size:1.6rem;line-height:1}
.dia-badge span{display:block;font-size:.66rem;letter-spacing:.09em;text-transform:uppercase;font-family:var(--ff-head);font-weight:700;margin-top:3px}
.dia-badge.sage{background:var(--sage)}
.dia-badge.tr{left:auto;right:-14px;top:24px;bottom:auto}
@media(max-width:520px){.dia{width:min(100%,330px)}.dia-badge{width:86px;height:86px;border-radius:20px}.dia-badge b{font-size:1.3rem}}
/* utility + header */
.utility{background:var(--brand);color:var(--ink);font-size:.84rem;overflow:hidden}
.uti-vp{overflow:hidden;padding-top:9px;padding-bottom:9px}
.uti-track{display:flex;justify-content:center}
.uti-set{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:6px 22px;text-align:center}
.uti-set+.uti-set{display:none}
.uti-set>.dot:last-child{display:none}
.utility b{font-family:var(--ff-head);font-weight:700}
.utility .dot{width:5px;height:5px;border-radius:50%;background:var(--ink);opacity:.45;flex:none}
@media(max-width:900px){
 .uti-vp{padding-top:8px;padding-bottom:8px}
 .uti-track{justify-content:flex-start;width:max-content;animation:ticker 30s linear infinite}
 .uti-set{flex-wrap:nowrap;white-space:nowrap;padding-right:22px}
 .uti-set+.uti-set{display:flex}
 .uti-set>.dot:last-child{display:block}
}
@keyframes ticker{from{transform:translateX(0)}to{transform:translateX(-50%)}}
@media (max-width:900px) and (prefers-reduced-motion:reduce){.uti-track{width:auto;justify-content:center}.uti-set{flex-wrap:wrap;white-space:normal;padding-right:0}.uti-set+.uti-set{display:none}}
.site-header{position:sticky;top:0;z-index:70;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 10px 30px -26px rgba(14,58,74,.5)}
.hdr{max-width:none;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:clamp(14px,2.2vw,40px);padding-top:13px;padding-bottom:13px}
.brand{display:inline-flex;align-items:center;gap:12px;flex:none;justify-self:start}
.brand img.logo{width:202px;max-width:50vw}
.brand img.ndis{height:42px;width:auto}
@media(max-width:1300px){.brand img.ndis{display:none}}
.nav{min-width:0;justify-self:center}
.nav ul{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:2px 4px;margin:0;padding:0;list-style:none}
.nav a{display:inline-block;white-space:nowrap;font-family:var(--ff-head);font-weight:600;font-size:.94rem;color:var(--ink);text-decoration:none;padding:10px 11px;border-radius:8px;transition:color var(--t),background-color var(--t)}
.nav a:hover{background:var(--brand-wash)}
.hdr-cta{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex:none;justify-self:end}
.hdr-call{display:inline-flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink)}
.hdr-call .ic{width:42px;height:42px;border-radius:50%;background:var(--brand-wash);color:var(--ink);display:grid;place-items:center;transition:background-color var(--t)}
.hdr-call:hover .ic{background:var(--brand)}
.hdr-call .ic svg{width:17px;height:17px}
.hdr-call span{display:block;font-size:.69rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-family:var(--ff-head);font-weight:600;line-height:1.3}
.hdr-call b{font-family:var(--ff-head);font-weight:700;font-size:1rem;white-space:nowrap;display:block}
.nav-toggle{position:absolute;opacity:0;pointer-events:none}
.burger{display:none;align-items:center;justify-content:center;width:50px;height:50px;border:1.5px solid var(--line-2);border-radius:12px;background:#fff;cursor:pointer;color:var(--ink)}
.burger svg{width:24px;height:24px}
.burger .x{display:none}
.nav-toggle:checked ~ .hdr .burger .bars{display:none}
.nav-toggle:checked ~ .hdr .burger .x{display:block}
.mobile-panel{display:none;background:#fff;border-top:1px solid var(--line);box-shadow:var(--sh-2)}
.nav-toggle:checked ~ .mobile-panel{display:block}
.mobile-panel ul{list-style:none;margin:0;padding:8px 0 20px}
.mobile-panel a{display:block;padding:13px var(--gut);font-family:var(--ff-head);font-weight:600;color:var(--ink);text-decoration:none;border-bottom:1px solid var(--line)}
.mobile-panel a:hover{background:var(--brand-wash)}
.mobile-actions{display:flex;gap:10px;padding:16px var(--gut) 6px;flex-wrap:wrap}
.mobile-actions .btn{flex:1 1 150px}
@media(max-width:1480px){.nav a{padding-left:8px;padding-right:8px;font-size:.9rem}.hdr{gap:clamp(12px,1.6vw,26px)}}
@media(max-width:1300px){.nav a{padding-left:7px;padding-right:7px;font-size:.87rem}.brand img.logo{width:186px}}
@media(max-width:1150px){.hdr-cta .hdr-call{display:none}}
@media(max-width:1000px){.nav,.hdr-cta .hdr-enq{display:none}.burger{display:inline-flex}}

/* ENQUIRY SLIDE-OUT */
.enq-toggle{position:absolute;opacity:0;pointer-events:none;width:1px;height:1px}
.enq-tab{position:fixed;right:0;top:32%;z-index:78;display:flex;flex-direction:column;align-items:center;cursor:pointer;border-radius:14px 0 0 14px;overflow:hidden;background:linear-gradient(180deg,var(--brand),var(--sage));box-shadow:-10px 18px 40px -18px rgba(14,58,74,.6);transition:transform var(--t),box-shadow var(--t)}
.enq-tab:hover{transform:translateX(-4px);box-shadow:-14px 20px 44px -16px rgba(14,58,74,.75)}
.enq-tab .label{writing-mode:vertical-rl;font-family:var(--ff-head);font-weight:800;letter-spacing:.2em;text-transform:uppercase;font-size:.78rem;color:var(--ink);padding:22px 13px 18px}
.enq-tab .go{width:100%;background:var(--ink);color:#fff;display:grid;place-items:center;padding:12px 0}
.enq-tab .go svg{width:20px;height:20px}
@media(max-width:900px){.enq-tab{display:none}}
.enq-veil{position:fixed;inset:0;z-index:95;background:rgba(14,58,74,.45);opacity:0;visibility:hidden;transition:opacity .3s ease,visibility .3s ease;cursor:pointer}
.enq-panel{position:fixed;top:0;right:0;z-index:96;height:100%;width:min(520px,100%);background:#fff;box-shadow:-30px 0 70px -30px rgba(14,58,74,.5);display:flex;flex-direction:column;overflow:hidden;clip-path:inset(0 0 0 100%);visibility:hidden;pointer-events:none;transition:clip-path .4s cubic-bezier(.4,0,.2,1),visibility .4s}
.enq-panel>*{transform:translateX(34px);transition:transform .42s cubic-bezier(.4,0,.2,1)}
.enq-toggle:checked ~ .enq-veil{opacity:1;visibility:visible}
.enq-toggle:checked ~ .enq-panel{clip-path:inset(0 0 0 0);visibility:visible;pointer-events:auto}
.enq-toggle:checked ~ .enq-panel>*{transform:none}
.enq-head{background:linear-gradient(120deg,var(--brand),var(--sage));color:var(--ink);padding:26px var(--gut);position:relative;flex:none}
.enq-head h2{font-size:1.45rem;margin:0 0 .3em;padding-right:54px}
.enq-head p{margin:0;font-size:.9rem;padding-right:54px;color:var(--ink);opacity:.82}
.enq-close{position:absolute;right:14px;top:14px;width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,.65);color:var(--ink);display:grid;place-items:center;cursor:pointer;transition:background-color var(--t),transform var(--t)}
.enq-close svg{width:16px;height:16px}
.enq-close:hover{background:#fff;transform:rotate(90deg)}
.enq-body{padding:24px var(--gut) 34px;overflow-y:auto;flex:1}
.enq-alt{margin-top:22px;padding:18px 20px;border:1px dashed var(--line-2);border-radius:var(--r);background:var(--sage-wash)}
.enq-alt p{margin:0 0 .5em;font-size:.93rem}
@media(max-width:560px){.enq-panel{width:100%}}
/* forms */
.fgrid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:15px}
.field{display:flex;flex-direction:column;gap:6px;min-width:0}
.field.full{grid-column:1/-1}
.field label{font-family:var(--ff-head);font-weight:600;font-size:.85rem;color:var(--ink)}
.field .req{color:var(--ink-soft)}
.field input,.field select,.field textarea{font-family:var(--ff-body);font-size:1rem;color:var(--ink);background:var(--cream);border:1.5px solid var(--line);border-radius:12px;padding:13px 15px;width:100%;min-width:0;min-height:52px}
.field textarea{min-height:124px;resize:vertical}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--brand);background:#fff;outline:3px solid rgba(97,187,220,.3)}
select option{background:#fff;color:var(--ink)}
.form-foot{margin-top:20px;display:flex;flex-wrap:wrap;align-items:center;gap:14px}
.form-foot p{margin:0;font-size:.84rem;color:var(--muted)}
@media(max-width:600px){.fgrid{grid-template-columns:1fr}}
/* HERO - light */
.hero{position:relative;color:var(--ink);overflow:hidden;background:var(--brand-wash);padding-bottom:clamp(68px,7vw,100px)}
.hero-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0}
.hero::after{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(to bottom,rgba(247,251,253,0) 62%,rgba(247,251,253,.6) 84%,#F7FBFD 100%),linear-gradient(104deg,rgba(234,245,250,.97) 0%,rgba(234,245,250,.9) 38%,rgba(186,219,195,.62) 76%,rgba(97,187,220,.5) 100%)}
.hero .dotlay{position:absolute;inset:0;z-index:2;background-image:var(--dots);background-size:17px 17px;opacity:.55;pointer-events:none}
.hero .wrap{position:relative;z-index:3}
.hero-grid{display:grid;grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);gap:clamp(30px,4.4vw,66px);align-items:center;padding-top:clamp(46px,5.4vw,84px)}
.hero h1{max-width:15ch}
.hero-sub{font-family:var(--ff-head);font-weight:700;font-size:clamp(1.25rem,2vw,1.66rem);line-height:1.26;margin:.25em 0 .55em;max-width:22ch;color:var(--ink)}
.hero-lede{color:var(--body);font-size:clamp(1.01rem,1.25vw,1.15rem);max-width:52ch}
.hero-actions{display:flex;flex-wrap:wrap;gap:14px;align-items:center;margin:30px 0 0}
.callpill{display:inline-flex;align-items:center;gap:13px;text-decoration:none;color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:var(--r-pill);padding:9px 24px 9px 9px;box-shadow:var(--sh-1);transition:transform var(--t),box-shadow var(--t)}
.callpill:hover{transform:translateY(-3px);box-shadow:var(--sh-2)}
.callpill .ic{width:46px;height:46px;border-radius:50%;background:var(--sage);color:var(--ink);display:grid;place-items:center;flex:none;transition:background-color var(--t)}
.callpill:hover .ic{background:var(--brand)}
.callpill .ic svg{width:19px;height:19px}
.callpill span{display:block;font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-family:var(--ff-head);font-weight:600}
.callpill b{display:block;font-family:var(--ff-head);font-weight:800;font-size:1.16rem}
@media(max-width:980px){.hero-grid{grid-template-columns:1fr}.hero-media{order:-1}.hero::after{background:linear-gradient(to bottom,rgba(247,251,253,0) 66%,#F7FBFD 100%),linear-gradient(168deg,rgba(234,245,250,.95) 0%,rgba(234,245,250,.93) 48%,rgba(221,238,228,.93) 100%)}}
/* QUICK BAR - detached from hero */
.quickbar-hold{position:relative;z-index:6;margin-bottom:clamp(58px,6.2vw,92px)}
.quickbar{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);box-shadow:var(--sh-2);display:grid;grid-template-columns:repeat(4,1fr);overflow:hidden}
.qa{display:flex;gap:15px;padding:clamp(24px,2.4vw,32px) clamp(18px,1.8vw,26px);text-decoration:none;border-right:1px solid var(--line);transition:background-color var(--t);min-width:0;cursor:pointer;position:relative}
.qa:last-child{border-right:0}
.qa::after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;background:var(--brand);transform:scaleX(0);transform-origin:left;transition:transform .3s ease}
.qa:hover{background:var(--brand-wash)}
.qa:hover::after{transform:scaleX(1)}
.qa .ic{width:52px;height:52px;border-radius:50%;background:var(--brand-wash);color:var(--ink);display:grid;place-items:center;flex:none;transition:background-color var(--t),transform var(--t)}
.qa .ic svg{width:22px;height:22px}
.qa:hover .ic{background:var(--brand);transform:rotate(-8deg) scale(1.06)}
.qa h3{font-size:1.04rem;margin:0 0 .2em}
.qa p{font-size:.88rem;margin:0;color:var(--body);line-height:1.5}
@media(max-width:1000px){.quickbar{grid-template-columns:1fr 1fr}.qa:nth-child(2){border-right:0}.qa:nth-child(1),.qa:nth-child(2){border-bottom:1px solid var(--line)}}
@media(max-width:600px){.quickbar{grid-template-columns:1fr}.qa{border-right:0;border-bottom:1px solid var(--line)}.qa:last-child{border-bottom:0}}
