/* featured answer block (AEO) */
.answer{position:relative;background:var(--sage-wash);border:1px solid var(--sage-tint);border-left:5px solid var(--sage);border-radius:0 var(--r) var(--r) 0;padding:20px 24px;font-size:1.02rem;color:var(--ink);max-width:none!important}
