.rail-card{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(20px,2vw,26px);box-shadow:var(--sh-1);min-width:0}
.rail-card.is-accent{background:linear-gradient(140deg,var(--brand),var(--sage));border-color:transparent;box-shadow:var(--sh-2);position:relative;overflow:hidden}
.rail-card.is-accent::after{content:"";position:absolute;right:-40px;bottom:-56px;width:150px;height:150px;border-radius:42px;transform:rotate(45deg);background:rgba(255,255,255,.28)}
.rail-card.is-accent>*{position:relative;z-index:1}
.rail-k{margin:0 0 10px;font-family:var(--ff-head);font-weight:800;font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ink);display:flex;align-items:center;gap:.6em}
.rail-k svg{width:16px;height:16px;color:var(--brand)}
