/* closing cta band */
.cta-band{background:linear-gradient(125deg,var(--brand) 0%,var(--brand-soft) 48%,var(--sage) 100%);border-radius:var(--r-xl);padding:clamp(28px,3.4vw,50px);position:relative;overflow:hidden;box-shadow:var(--sh-2)}
