.loc-menu a:hover{transform:translateY(-6px);box-shadow:var(--sh-2);border-color:var(--brand-tint)}
.loc-menu-ic{width:54px;height:54px;border-radius:16px;background:var(--brand-wash);color:var(--ink);display:grid;place-items:center;transition:background-color var(--t),transform var(--t)}
.loc-menu-ic svg{width:24px;height:24px}
.loc-menu a:hover .loc-menu-ic{background:var(--sage);transform:rotate(-8deg)}
.loc-menu b{display:block;font-family:var(--ff-head);font-weight:700;color:var(--ink);font-size:1.02rem;line-height:1.3}
.loc-menu span.d{display:block;font-size:.88rem;color:var(--body);margin-top:5px;line-height:1.5}
@media(max-width:940px){.loc-menu{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.loc-menu{grid-template-columns:1fr}}
/* areas */
.loc-areas-in{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,3.6vw,58px);align-items:center}
