.areas-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(14px,1.7vw,20px)}
.area{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(20px,2.1vw,26px);min-width:0;transition:transform .3s ease,box-shadow var(--t),border-color var(--t)}
.area:hover{transform:translateY(-5px);box-shadow:var(--sh-2);border-color:var(--brand-tint)}
