.loc-field{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(22px,2.4vw,34px);box-shadow:var(--sh-1);text-align:center;margin-top:clamp(28px,3.4vw,48px)}
.loc-field .k{margin:0 0 14px;justify-content:center;font-family:var(--ff-head);font-weight:800;font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ink);display:flex;align-items:center;gap:.6em}
.loc-field .k svg{width:16px;height:16px;color:var(--brand)}
.loc-field ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:9px;justify-content:center}
.loc-field li{min-width:0}
.loc-field li span,.loc-field li a{display:inline-block;font-family:var(--ff-head);font-weight:600;font-size:.86rem;color:var(--ink);background:var(--brand-wash);border:1px solid var(--brand-tint);border-radius:var(--r-pill);padding:7px 14px;text-decoration:none;transition:background-color var(--t),transform var(--t)}
.loc-field li a:hover{background:var(--brand);transform:translateY(-2px)}
.loc-here{display:inline-flex;align-items:center;gap:.5em;font-family:var(--ff-head);font-weight:800;font-size:.86rem;color:var(--ink);background:var(--sage)!important;border-color:var(--sage)!important;border-radius:var(--r-pill);padding:7px 14px;margin-bottom:10px}
