.lhero-reach span.a:last-child::after{display:none}

/* ---------- ask-us assistant (pure CSS, no JS needed) ---------- */
.bot-toggle,.bq{position:absolute;opacity:0;pointer-events:none;width:1px;height:1px;margin:0}
.bot-fab{position:fixed;right:20px;bottom:20px;z-index:77;width:64px;height:64px;border-radius:50%;cursor:pointer;
 background:linear-gradient(140deg,var(--brand),var(--sage));color:var(--ink);display:grid;place-items:center;
 box-shadow:0 16px 34px -12px rgba(14,58,74,.55);transition:transform .3s cubic-bezier(.34,1.3,.64,1),box-shadow var(--t)}
.bot-fab:hover{transform:translateY(-4px) scale(1.05);box-shadow:0 20px 40px -12px rgba(14,58,74,.65)}
.bot-fab svg{width:27px;height:27px}
.bot-fab .ic-x{display:none}
.bot-fab::after{content:"";position:absolute;inset:-6px;border-radius:50%;border:2px solid var(--brand);opacity:.55;animation:botPing 2.6s ease-out infinite;pointer-events:none}
@keyframes botPing{0%{transform:scale(.92);opacity:.55}70%{transform:scale(1.22);opacity:0}100%{opacity:0}}
.bot-toggle:checked ~ .bot-fab .ic-chat{display:none}
.bot-toggle:checked ~ .bot-fab .ic-x{display:block}
.bot-toggle:checked ~ .bot-fab::after{display:none}
.bot-nudge{position:fixed;right:96px;bottom:34px;z-index:76;background:#fff;border:1px solid var(--line);border-radius:var(--r-pill);
 padding:10px 18px;font-family:var(--ff-head);font-weight:700;font-size:.86rem;color:var(--ink);box-shadow:var(--sh-2);
 cursor:pointer;white-space:nowrap;animation:rvIn .6s .8s both}
.bot-nudge::after{content:"";position:absolute;right:-6px;top:50%;width:12px;height:12px;background:#fff;border-right:1px solid var(--line);border-top:1px solid var(--line);transform:translateY(-50%) rotate(45deg)}
.bot-toggle:checked ~ .bot-nudge{display:none}
@media(max-width:760px){.bot-nudge{display:none}}
.bot-panel{position:fixed;right:20px;bottom:98px;z-index:78;width:min(390px,calc(100vw - 40px));max-height:min(620px,calc(100vh - 150px));
 background:#fff;border:1px solid var(--line);border-radius:var(--r-xl);box-shadow:0 36px 80px -30px rgba(14,58,74,.5);
 display:flex;flex-direction:column;overflow:hidden;transform-origin:bottom right;
 opacity:0;visibility:hidden;transform:translateY(14px) scale(.96);transition:opacity .28s ease,transform .28s cubic-bezier(.34,1.2,.64,1),visibility .28s}
.bot-toggle:checked ~ .bot-panel{opacity:1;visibility:visible;transform:none}
.bot-head{background:linear-gradient(130deg,var(--brand),var(--sage));padding:18px 20px;display:grid;grid-template-columns:46px 1fr auto;gap:13px;align-items:center;flex:none}
.bot-head .av{width:46px;height:46px;border-radius:50%;background:#fff;display:grid;place-items:center;box-shadow:var(--sh-1)}
.bot-head .av svg{width:23px;height:23px;color:var(--ink)}
.bot-head b{display:block;font-family:var(--ff-head);font-weight:800;color:var(--ink);font-size:1.02rem;line-height:1.2}
.bot-head span{display:block;font-size:.8rem;color:var(--ink);opacity:.8;margin-top:2px}
.bot-head .x{width:34px;height:34px;border-radius:50%;background:rgba(255,255,255,.6);color:var(--ink);display:grid;place-items:center;cursor:pointer;transition:background-color var(--t),transform var(--t)}
.bot-head .x svg{width:14px;height:14px}
.bot-head .x:hover{background:#fff;transform:rotate(90deg)}
.bot-body{padding:18px 20px 22px;overflow-y:auto;flex:1;background:var(--cream)}
.bot-msg{background:#fff;border:1px solid var(--line);border-radius:4px 16px 16px 16px;padding:13px 16px;font-size:.92rem;color:var(--body);line-height:1.6;box-shadow:var(--sh-1);margin-bottom:16px}
.bot-msg b{color:var(--ink)}
.bot-k{margin:0 0 10px;font-family:var(--ff-head);font-weight:800;font-size:.72rem;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}
.bot-chips{display:grid;gap:8px;margin-bottom:18px}
.bot-qa{display:grid;gap:8px;min-width:0}
.bot-chips label{display:flex;align-items:center;justify-content:space-between;gap:10px;background:#fff;border:1px solid var(--line-2);border-radius:var(--r-pill);
 padding:11px 16px;font-family:var(--ff-head);font-weight:600;font-size:.88rem;color:var(--ink);cursor:pointer;line-height:1.35;
 transition:background-color var(--t),border-color var(--t),transform var(--t)}
.bot-chips label svg{width:13px;height:13px;color:var(--brand);flex:none;transition:transform var(--t)}
.bot-chips label:hover{background:var(--brand-wash);border-color:var(--brand);transform:translateX(3px)}
.bot-ans{display:none;background:var(--brand-wash);border:1px solid var(--brand-tint);border-radius:16px 16px 16px 4px;padding:14px 17px;font-size:.9rem;color:var(--ink);line-height:1.62;margin:0 0 4px;animation:rvIn .35s both}
.bot-acts .wa .ic{background:#E3F7EA;color:#25D366}
.bot-ans a{color:var(--ink);font-weight:700}
.bq.q1:checked ~ .bot-body .a1,.bq.q2:checked ~ .bot-body .a2,.bq.q3:checked ~ .bot-body .a3,.bq.q4:checked ~ .bot-body .a4,.bq.q5:checked ~ .bot-body .a5,.bq.q6:checked ~ .bot-body .a6,.bq.q7:checked ~ .bot-body .a7{display:block}
.bq.q1:checked ~ .bot-body .w1>label,.bq.q2:checked ~ .bot-body .w2>label,.bq.q3:checked ~ .bot-body .w3>label,.bq.q4:checked ~ .bot-body .w4>label,.bq.q5:checked ~ .bot-body .w5>label,.bq.q6:checked ~ .bot-body .w6>label,.bq.q7:checked ~ .bot-body .w7>label{background:var(--brand-wash);border-color:var(--brand);font-weight:800}
.bq.q1:checked ~ .bot-body .w1>label svg,.bq.q2:checked ~ .bot-body .w2>label svg,.bq.q3:checked ~ .bot-body .w3>label svg,.bq.q4:checked ~ .bot-body .w4>label svg,.bq.q5:checked ~ .bot-body .w5>label svg,.bq.q6:checked ~ .bot-body .w6>label svg,.bq.q7:checked ~ .bot-body .w7>label svg{transform:rotate(90deg)}
.bot-foot{border-top:1px dashed var(--line-2);padding-top:16px}
.bot-foot .bot-k{margin-bottom:12px}
.bot-acts{display:grid;gap:8px}
.bot-acts a,.bot-acts label{display:grid;grid-template-columns:38px 1fr auto;gap:12px;align-items:center;background:#fff;border:1px solid var(--line);
 border-radius:var(--r);padding:11px 14px;text-decoration:none;cursor:pointer;min-width:0;transition:border-color var(--t),background-color var(--t),transform var(--t)}
.bot-acts a:hover,.bot-acts label:hover{border-color:var(--brand-tint);background:var(--brand-wash);transform:translateY(-2px)}
.bot-acts .ic{width:38px;height:38px;border-radius:50%;background:var(--brand-wash);color:var(--ink);display:grid;place-items:center}
.bot-acts .ic svg{width:17px;height:17px}
.bot-acts b{display:block;font-family:var(--ff-head);font-weight:700;color:var(--ink);font-size:.9rem;line-height:1.25}
.bot-acts span.d{display:block;font-size:.78rem;color:var(--muted);margin-top:2px;overflow-wrap:anywhere}
.bot-acts .go{width:24px;height:24px;border-radius:50%;background:var(--sage);color:var(--ink);display:grid;place-items:center}
.bot-acts .go svg{width:11px;height:11px}
.bot-acts .fb .ic{background:#E7F0FE;color:#1877F2}
@media(max-width:480px){
 .bot-fab{width:58px;height:58px;right:16px;bottom:16px}
 .bot-panel{right:16px;left:16px;width:auto;bottom:86px;max-height:calc(100vh - 130px)}
}
@media(prefers-reduced-motion:reduce){.bot-fab::after{animation:none}}

/* section rhythm */
.svc-block + .svc-block,.svc-block + .cta-band,.svc-block + .faq,article + .cta-band{margin-top:clamp(34px,4.2vw,58px)}
